#include <bits/stdc++.h>
#define endl '\n'
using namespace std;

const int N = 10;
const int V = 203;
const int INF = 1000000000;

string g[N];
int scientists[N][N] = {};
int rescue_capacity[N][N] = {};
int infection[N][N] = {};
int reach_time[N*N][N*N] = {};
int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};

vector<int> adj[V];
int cap[V][V], flow[V][V], it[V], level[V], par[V];

bool build_level(int s, int t) {
    memset(level, -1, sizeof level);
    level[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (cap[u][v] > flow[u][v] && level[v] == -1) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[t] != -1;
}

bool dfs_aug(int u, int t) {
    if (u == t) return true;
    for (int &i = it[u]; i < (int)adj[u].size(); ++i) {
        int v = adj[u][i];
        if (level[v] == level[u] + 1 && cap[u][v] > flow[u][v] && dfs_aug(v, t)) {
            par[v] = u;
            return true;
        }
    }
    return false;
}

void edge_add(int u, int v, int c) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    cap[u][v] += c;
}

int maxflow(int s, int t) {
    int ans = 0;
    while (build_level(s, t)) {
        memset(it, 0, sizeof it);
        while (true) {
            memset(par, -1, sizeof par);
            par[s] = 0;
            if (!dfs_aug(s, t)) break;
            int add = INF;
            for (int v = t, u = par[v]; v != s; v = u, u = par[v]) {
                add = min(add, cap[u][v] - flow[u][v]);
            }
            for (int v = t, u = par[v]; v != s; v = u, u = par[v]) {
                flow[u][v] += add;
                flow[v][u] -= add;
            }
            ans += add;
        }
    }
    return ans;
}

inline int flat(int n, int i, int j) {
    return i * n + j;
}

int node_number(int n, int i, int j, bool right) {
    return flat(n, i, j) + (right ? n * n : 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, t;
    cin >> n >> t;
    string line;
    pair<int,int> bomb;

    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] == 'Y') {
                g[i][j] = 'Y';
            } else if (line[j] == 'Z') {
                g[i][j] = 'Z';
                bomb = {i, j};
            } else {
                g[i][j] = '.';
                scientists[i][j] += line[j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] != 'Y' && line[j] != 'Z') {
                rescue_capacity[i][j] += line[j] - '0';
            }
        }
    }

    memset(infection, -1, sizeof infection);
    infection[bomb.first][bomb.second] = 0;
    queue<pair<int,int>> q;
    q.push(bomb);
    while (!q.empty()) {
        int i = q.front().first, j = q.front().second;
        q.pop();
        for (auto &dir : dirs) {
            int ni = i + dir[0], nj = j + dir[1];
            if (0 <= ni && ni < n && 0 <= nj && nj < n && g[ni][nj] == '.' && infection[ni][nj] == -1) {
                infection[ni][nj] = infection[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }

    memset(reach_time, -1, sizeof reach_time);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (g[i][j] != '.') continue;
            int start = flat(n, i, j);
            reach_time[start][start] = 0;
            queue<pair<int,int>> q;
            q.push({i, j});
            while (!q.empty()) {
                int ii = q.front().first, jj = q.front().second;
                q.pop();
                int cur_id = flat(n, ii, jj);
                if (infection[ii][jj] == -1 || reach_time[start][cur_id] < infection[ii][jj]) {
                    for (auto &dir : dirs) {
                        int ni = ii + dir[0], nj = jj + dir[1];
                        if (0 <= ni && ni < n && 0 <= nj && nj < n && g[ni][nj] == '.') {
                            int nid = flat(n, ni, nj);
                            if ((infection[ni][nj] == -1 || reach_time[start][cur_id] + 1 <= infection[ni][nj])
                                && reach_time[start][nid] == -1) {
                                reach_time[start][nid] = reach_time[start][cur_id] + 1;
                                q.push({ni, nj});
                            }
                        }
                    }
                }
            }
        }
    }

    int src = 2 * n * n;
    int sink = src + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (scientists[i][j]) edge_add(src, node_number(n, i, j, false), scientists[i][j]);
            if (rescue_capacity[i][j]) edge_add(node_number(n, i, j, true), sink, rescue_capacity[i][j]);
            int start = flat(n, i, j);
            for (int ii = 0; ii < n; ++ii) {
                for (int jj = 0; jj < n; ++jj) {
                    int target = flat(n, ii, jj);
                    if (reach_time[start][target] >= 0 && reach_time[start][target] <= t) {
                        edge_add(node_number(n, i, j, false), node_number(n, ii, jj, true), INF);
                    }
                }
            }
        }
    }

    cout << maxflow(src, sink) << endl;
    return 0;
}
